import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { LinkButton } from "@/components/ui/button"
import { SemanticContent } from "@/components/ui/semantic-content"

/** Account summary: identity (avatar, name, email), key/value rows and up to two links. */
export default function AccountSummary({
  heading = "Account",
  identity = { name: "Alex Morgan", email: "alex@example.com" },
  rows = [
    { label: "Plan", value: "Team" },
    { label: "Member since", value: "March 2026" },
    { label: "Seats", value: "8 of 10" },
  ],
  actions = [
    { label: "Manage account", href: "#" },
    { label: "Billing", href: "#" },
  ],
}: {
  heading?: string
  identity?: { name: string; email?: string; avatar?: string }
  rows?: { label: string; value: string }[]
  actions?: { label: string; href: string }[]
}) {
  const initials = identity.name.split(/\s+/).map((p) => p[0]).slice(0, 2).join("").toUpperCase()
  return (
    <section data-slot="account-summary" className="py-8">
      <div className="mx-auto max-w-3xl px-6">
        <SemanticContent as="h2" className="text-xl">{heading}</SemanticContent>
        <div className="mt-4 flex items-center gap-4">
          <Avatar size="lg">
            {identity.avatar && <AvatarImage src={identity.avatar} alt="" />}
            <AvatarFallback>{initials}</AvatarFallback>
          </Avatar>
          <div className="min-w-0">
            <SemanticContent as="p" className="truncate font-medium">{identity.name}</SemanticContent>
            {identity.email && <SemanticContent as="small" className="block truncate">{identity.email}</SemanticContent>}
          </div>
        </div>
        <SemanticContent as="dl" className="mt-6 divide-y divide-border border-y border-border">
          {rows.map((r) => (
            <div key={r.label} className="flex items-center justify-between gap-4 py-3">
              <SemanticContent as="dt">{r.label}</SemanticContent>
              <SemanticContent as="dd" className="text-right text-foreground">{r.value}</SemanticContent>
            </div>
          ))}
        </SemanticContent>
        {actions.length > 0 && (
          <div className="mt-6 flex flex-wrap gap-2">
            {actions.slice(0, 2).map((a, i) => (
              <LinkButton key={a.label} href={a.href} variant={i === 0 ? "default" : "outline"}>
                {a.label}
              </LinkButton>
            ))}
          </div>
        )}
      </div>
    </section>
  )
}
